    @classmethod
    def _events_in_boundary(
        cls,
        events: Sequence[Mapping[str, Any]],
        boundary: Mapping[str, Any],
    ) -> list[dict[str, Any]]:
        mode = boundary.get("mode")
        if mode == "automatic":
            floor = int(boundary.get("min_seq_exclusive", -1))
            selected = [dict(event) for event in events if int(event.get("seq", -1)) > floor]
            return sorted(selected, key=lambda event: int(event.get("seq", -1)))
        if mode == "manual":
            start = _parse_datetime(boundary.get("start"))
            end = _parse_datetime(boundary.get("end"))
            selected = [
                dict(event)
                for event in events
                if start <= _parse_datetime(event.get("timestamp")) <= end
            ]
            return sorted(selected, key=lambda event: int(event.get("seq", -1)))
        raise ValueError(f"unsupported causal boundary mode: {mode!r}")

    @classmethod
    def _project_events(
        cls,
        events: Sequence[Mapping[str, Any]],
        expected_payloads: Mapping[str, Mapping[str, Any]],
    ) -> list[dict[str, Any]]:
        projected: list[dict[str, Any]] = []
        for event in events:
            event_type = str(event.get("type") or "")
            if event_type in _NON_DURABLE_EVENT_TYPES:
                continue
            payload = _event_payload(event)
            labels = [
                label
                for label, wanted in expected_payloads.items()
                if _record_exact(payload, wanted)
            ]
            label = labels[0] if len(labels) == 1 else f"unexpected:{event_type}:{event.get('seq')}"
            projected.append({"label": label, "payload": payload, "events": [dict(event)]})
        return projected

