    def _resolve_boundary(context: Mapping[str, Any], params: Mapping[str, Any]) -> dict[str, Any]:
        initialization = context.get("initialization")
        metadata = initialization.get("metadata") if isinstance(initialization, Mapping) else None
        if isinstance(metadata, Mapping) and "baseline_max_event_seq" in metadata:
            return {
                "mode": "automatic",
                "min_seq_exclusive": int(metadata["baseline_max_event_seq"]),
            }
        start = str(params.get("manual_window_start") or "")
        end = str(params.get("manual_window_end") or "")
        if start != MANUAL_WINDOW_START or end != MANUAL_WINDOW_END:
            raise ValueError("manual causal window does not match the task ruleset")
        return {"mode": "manual", "start": start, "end": end}

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        observed: dict[str, Any] = {"applications": []}
        try:
            if params.get("expected_instruction_sha256") != INSTRUCTION_SHA256:
                raise ValueError("task instruction SHA-256 does not match evaluator")
            if params.get("expected_ruleset_sha256") != RULESET_SHA256:
                raise ValueError("task ruleset SHA-256 does not match evaluator")
            if params.get("source_simulator_name") != SOURCE_SIMULATOR_NAME:
                raise ValueError("source simulator name does not match evaluator")
            if params.get("ios_device_profile") != IOS_DEVICE_PROFILE:
                raise ValueError("iOS device profile does not match evaluator")
            if bool(params.get("requires_ui_observation")):
                raise ValueError("this evaluator forbids UI observation and Appium sessions")
            bundle_id = str(params.get("bundle_id") or DEFAULT_BUNDLE_ID)
            if bundle_id != DEFAULT_BUNDLE_ID:
                raise ValueError("OpenBank bundle id does not match evaluator")
            db_path = str(params.get("db_path") or "").strip()
            data_container_path = str(params.get("data_container_path") or "").strip()
            if db_path:
                store = OpenBankStore(
                    db_path,
                    bundle_id=bundle_id,
                    data_container_path=data_container_path or None,
                    local_state_key=LOCAL_STATE_KEY,
                )
            else:
                udid = str(params.get("udid") or "").strip()
                if not udid:
                    raise ValueError("bound iOS runtime UDID is required")
                store = OpenBankStore.from_simulator(udid, bundle_id=bundle_id)
                observed["udid"] = udid
            state = store.read_state()
            if store.local_state_key != LOCAL_STATE_KEY:
                raise ValueError(f"expected {LOCAL_STATE_KEY}, got {store.local_state_key}")
            observed.update(
                {
                    "local_state_key": store.local_state_key,
                    "db_path": str(store.db_path),
                    "data_container_path": (
                        str(store.data_container_path) if store.data_container_path else None
                    ),
                    "applications": [
                        {
                            "bundle_id": bundle_id,
                            "identity_source": "bound OpenBank data container",
                        }
                    ],
                }
            )
            boundary = self._resolve_boundary(context, params)
            return self.evaluate_state(state, boundary=boundary, observed=observed)
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"OpenBank4 evaluator error: {type(exc).__name__}: {exc}",
                metadata={
                    "read_only": True,
                    "task_id": TASK_ID,
                    "evaluator_id": EVALUATOR_ID,
                    "instruction_sha256": INSTRUCTION_SHA256,
                    "ruleset_sha256": RULESET_SHA256,
                    "observed": observed,
                    "exception_type": type(exc).__name__,
                },
            )
